import { brokerEnabled, brokerUsageSummary, foldUsageByPerson } from '../../../src/core/broker-client.mjs';
import { getStats, shapingGroups, reviewQuality } from '../../../src/core/stats.mjs';
import { badRequest } from '../../server.mjs';

export function register(app) {

// ---------------------------------------------------------------------------
// GET /api/stats?range=today|week|month|lastMonth|custom|all[&from&to][&tag…][&person][&groupBy][&byTag=1[&tagKey…]][&report=1]
//   -> the Statistics view payload (§6.9). A bad range/filter/groupBy is the caller's fault: getStats'
//   RangeError maps to 400. The broker's per-person card is skipped while a filter is active (it
//   cannot be narrowed by tag).
app.get('/api/stats', async (req, res) => {
  const str = (v) => (typeof v === 'string' && v ? v : null);
  let stats;
  try {
    const q = req.query;
    stats = getStats({
      range: str(q.range) || 'month',
      from: str(q.from), to: str(q.to),
      filter: { tags: q.tag == null ? [] : [].concat(q.tag), person: str(q.person) },
      groupBy: str(q.groupBy),
      tagKeys: q.byTag === '1' ? (q.tagKey == null ? [] : [].concat(q.tagKey)) : null,
      report: q.report === '1',
    });
  } catch (err) {
    if (err instanceof RangeError) return badRequest(res, err.message);
    return res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
  // Credential broker: model spend per person in the same window, as the broker metered it
  // (the authoritative figure: it saw every request). Absent with the broker off.
  if (brokerEnabled() && !stats.filtered) stats.byPerson = await statsByPerson(stats.windowStartMs, stats.windowEndMs);
  // Shaper (D28): shaped vs unshaped runs of the same size.
  stats.shaping = shapingGroups(stats.range === 'all' ? 0 : stats.windowStartMs, stats.windowEndMs);
  res.json(stats);
});

// ---------------------------------------------------------------------------
// GET /api/stats/review-quality[?startMs=&endMs=] -> { startMs, endMs, runs, roles } (#990 s6): per-role review counts
//   of finished runs started in [startMs, endMs), default all time. A malformed window is a 400 and runs no query; a DB
//   failure is a fixed 500 that never carries the DB message.
app.get('/api/stats/review-quality', (req, res) => {
  const ms = (v, fallback) => (v == null || v === '' ? fallback : typeof v === 'string' && /^\d{1,15}$/.test(v) ? Number(v) : NaN);
  const startMs = ms(req.query.startMs, 0);
  const endMs = ms(req.query.endMs, Date.now() + 1);
  if (!Number.isInteger(startMs) || !Number.isInteger(endMs) || endMs <= startMs) {
    return badRequest(res, 'startMs and endMs must be whole milliseconds with startMs before endMs');
  }
  try {
    res.json({ startMs, endMs, ...reviewQuality(startMs, endMs) });
  } catch (err) {
    console.error('[stats] review quality:', err);
    res.status(500).json({ error: 'review quality unavailable' });
  }
});

/** Broker usage in [startMs, endMs) folded per person: {people:[…]} or {error}. */
async function statsByPerson(startMs, endMs) {
  try {
    const { rows } = await brokerUsageSummary({
      since: Number.isFinite(startMs) ? new Date(startMs).toISOString() : undefined,
      until: Number.isFinite(endMs) ? new Date(endMs).toISOString() : undefined,
    });
    return { people: foldUsageByPerson(rows) };
  } catch (err) {
    return { error: err && err.message ? err.message : String(err) };
  }
}
}
